// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    address dao;
    address asset;

    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); dao = address(new __InvMutHandleStub()); asset = dao; c.setDAO(dao); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 warpForward) public {
        vm.assume(amount > 0);
        unlockTime = bound(unlockTime, 0, 1e12);
        warpForward = bound(warpForward, unlockTime + 1, unlockTime + 1e12);

        // configure flash governance as a "successful proposal" (configured == false so it passes)
        vm.prank(dao);
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // deposit the flash governance stake via DAO (flashEnabled allows DAO)
        vm.prank(dao);
        c.assertGovernanceApproved(dao, address(c), false);

        // let the unlock time pass
        vm.warp(block.timestamp + warpForward);

        // withdraw succeeds on both versions
        vm.prank(dao);
        c.withdrawGovernanceAsset(address(c), asset);

        // RULE: after a successful withdrawal the pending decision is cleared -> amount == 0
        (uint256 amt, , , ) = c.pendingFlashDecision(address(c), dao);
        assertTrue(amt == 0);
    }
}
